import{_ as t,c as s,o as a,ae as o}from"./chunks/framework.70bNUV4I.js";const p=JSON.parse('{"title":"Physics: Transform Smoothing","description":"","frontmatter":{},"headers":[],"relativePath":"samples/Physics/smoothing.md","filePath":"samples/Physics/smoothing.md"}'),i={name:"samples/Physics/smoothing.md"};function r(n,e,h,l,m,d){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="physics-transform-smoothing" tabindex="-1">Physics: Transform Smoothing <a class="header-anchor" href="#physics-transform-smoothing" aria-label="Permalink to &quot;Physics: Transform Smoothing&quot;">​</a></h1><p>Transform smoothing is a small runtime feature that interpolates rendered object transforms between physics updates. It helps remove jitter and makes physics-driven objects appear visually smoother when rendering runs at a different rate than the physics simulation.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>When smoothing is enabled, the renderer uses an interpolated transform between the most recent physics snapshots instead of snapping directly to the latest simulation result every frame. This reduces visible jitter when frame rate and physics update frequency differ.</p><h2 id="trade-off" tabindex="-1">Trade-off <a class="header-anchor" href="#trade-off" aria-label="Permalink to &quot;Trade-off&quot;">​</a></h2><p>Smoothing introduces a small temporal offset (approximately 16 ms in current engine defaults). That means visuals are slightly delayed relative to the simulation. Use smoothing when visual stability is more important than absolute input-response immediacy.</p><h2 id="how-to-enable-disable" tabindex="-1">How to enable / disable <a class="header-anchor" href="#how-to-enable-disable" aria-label="Permalink to &quot;How to enable / disable&quot;">​</a></h2><p>Use the physics system API to toggle smoothing at runtime:</p><ul><li>Enable smoothing: <code>GetPhysicsSystem()-&gt;setEnableSmoothing(true);</code></li><li>Disable smoothing: <code>GetPhysicsSystem()-&gt;setEnableSmoothing(false);</code></li></ul><p>These calls affect how transforms are produced for rendering; physics simulation and authoritative state remain unchanged.</p><p>See also:</p><p><a href="https://odevu.github.io/VEX/classvex_1_1PhysicsSystem.html" target="_blank" rel="noreferrer">Physics API reference</a></p>',12)])])}const f=t(i,[["render",r]]);export{p as __pageData,f as default};
